/**
 * Пропуск месяца на январь–март 2027 (владелец 2026-11-04: «с января по июнь можно добавить миссии: в январе праздник пончиков, в феврале
 * день влюблённых, потом пасхальный праздник»). По три миссии ~10 минут, только `choice` и `build` (новые реплики не озвучены).
 * Даты проверены: Tłusty Czwartek 2027 — 4 февраля, Niedziela Palmowa — 21 марта, Wielkanoc — 28 марта, Śmigus-dyngus — 29 марта.
 * Названия мест — контекст учебных ситуаций, без партнёрства; цены — учебные.
 */
import type { I18n } from '@polski-go/shared';
import { t } from './builders';
import type { Mission } from './missions';
import { P, T, bd, ch, narr, npc } from './mission-scenes-a';

export const SEASON_MISSION_MINUTES = 10;
const ANSWER = t('Відповідай.', 'Ответь.', 'Answer.');
const UNDERSTAND = t('Що це означає?', 'Что это значит?', 'What does it mean?');
const AMOUNT = t('Скільки разом? (навчальна сума)', 'Сколько всего? (учебная сумма)', 'How much in total? (practice amount)');
export const ph = (pl: string, uk: string, ru: string, en: string) => ({ pl, tr: t(uk, ru, en) });

type Body = Omit<Mission, 'category' | 'minutes' | 'xp' | 'zlotki' | 'season' | 'tags'> & { tags?: string[] };
/** Миссия сезона: ~10 минут, 70 XP и 35 Złotki (как обычные миссии со второй сценой), тег сезона для достижения. */
export const seasonMission = (season: string, m: Body): Mission => ({
  category: 'season', minutes: SEASON_MISSION_MINUTES, xp: 70, zlotki: 35, season, ...m, tags: [`season-${season}`, ...(m.tags ?? [])],
});
const role = (uk: string, ru: string, en: string): I18n => t(uk, ru, en);

